    private static void catalog(GameTestHelper h){ScopedPrototypeCatalogFixture.replace(h,ModCharacters.CHARACTER_TYPE,c->{var id=ModCharacters.HUMAN_ID;var j=com.juicyslew.moonstation14.component.codec.json.CharacterData.CODEC.encodeStart(com.mojang.serialization.JsonOps.INSTANCE,c.get(id)).getOrThrow().getAsJsonObject();var a=j.has("components")?j.getAsJsonArray("components"):new com.google.gson.JsonArray();j.add("components",a);com.juicyslew.moonstation14.ms14.character.CharacterPrototypeComponentUpsert.upsert(a,com.google.gson.JsonParser.parseString("{\"type\":\"CombatMode\",\"can_disarm\":true}").getAsJsonObject());com.juicyslew.moonstation14.ms14.character.CharacterPrototypeComponentUpsert.upsert(a,com.google.gson.JsonParser.parseString("{\"type\":\"MeleeWeapon\",\"weapon\":{\"damage\":{\"blunt\":5}}}").getAsJsonObject());c.put(id,com.juicyslew.moonstation14.component.codec.json.CharacterData.CODEC.parse(com.mojang.serialization.JsonOps.INSTANCE,j).getOrThrow());return c;});}
