    private static void run(GameTestHelper h,boolean cancel){var f=player(h);var bodies=new net.minecraft.world.entity.LivingEntity[2];
        var cancelled=new java.util.concurrent.atomic.AtomicBoolean();
        Object cancelListener=new Object(){@net.neoforged.bus.api.SubscribeEvent public void onDamage(LivingIncomingDamageEvent e){if(e.getEntity()==bodies[1]){cancelled.set(true);e.setCanceled(true);}}};
        h.testInfo.addListener(new net.minecraft.gametest.framework.GameTestListener(){private void close(net.minecraft.gametest.framework.GameTestInfo i){NeoForge.EVENT_BUS.unregister(cancelListener);for(var b:bodies)if(b!=null&&!b.isRemoved())b.discard();f.close();}@Override public void testStructureLoaded(net.minecraft.gametest.framework.GameTestInfo i){}@Override public void testPassed(net.minecraft.gametest.framework.GameTestInfo i,net.minecraft.gametest.framework.GameTestRunner r){close(i);}@Override public void testFailed(net.minecraft.gametest.framework.GameTestInfo i,net.minecraft.gametest.framework.GameTestRunner r){close(i);}@Override public void testAddedForRerun(net.minecraft.gametest.framework.GameTestInfo o,net.minecraft.gametest.framework.GameTestInfo n,net.minecraft.gametest.framework.GameTestRunner r){close(o);}});
        try{h.runAtTickTime(2,()->{try{var active=RegisteredPlayerReadyDriver.readyAndQuery(f);var attacker=active.body();bodies[0]=attacker;BlockPos p=h.absolutePos(new BlockPos(3,2,3));for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)h.getLevel().setBlock(p.offset(x,-1,z),Blocks.STONE.defaultBlockState(),3);attacker.teleportTo(p.getX()+.5,p.getY(),p.getZ()+.5);attacker.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);attacker.tick();var target=EntityType.VILLAGER.create(h.getLevel());if(target==null)throw new GameTestAssertException("target create failed");bodies[1]=target;target.setNoAi(true);target.setPos(p.getX()+.5,p.getY(),p.getZ()+.9);h.getLevel().addFreshEntity(target);if(com.juicyslew.moonstation14.ms14.player_body_control.server.ActiveCharacterPolicy.resolveActor(target).flatMap(c->c.component(com.juicyslew.moonstation14.ms14.character.components.StaminaPrototypeComponent.class)).isEmpty())throw new GameTestAssertException("target has no resolved stamina capability");var sel=MeleeWeaponResolver.resolve(attacker).orElseThrow();var beforeDamage=typed(target);float hp=target.getHealth();float stamina=com.juicyslew.moonstation14.ms14.character.stamina.StaminaSystem.state(target).damage();if(cancel){NeoForge.EVENT_BUS.register(cancelListener);}CombatModeRequestService.handle(f.player(),new CombatModeRequest(active.epoch(),1,true));var reply=MeleeAttackRequestService.handle(f.player(),new MeleeAttackRequest(active.epoch(),1,sel.kind(),sel.handRevision(),sel.activeHand(),sel.itemToken().orElse(""),target.getUUID()));float afterStamina=com.juicyslew.moonstation14.ms14.character.stamina.StaminaSystem.state(target).damage();if(reply.status()!=MeleeAttackReply.Status.HIT||!reply.cooldownConsumed())throw new GameTestAssertException("registered melee request did not hit");if(cancel){if(!cancelled.get()||Math.abs(typed(target)-beforeDamage)>.011f||Math.abs(target.getHealth()-hp)>.011f||Math.abs(afterStamina-stamina)>.011f)throw new GameTestAssertException("cancelled native hit committed typed damage/stamina");}else if(Math.abs((typed(target)-beforeDamage)-5f)>.011f||Math.abs((hp-target.getHealth())-1f)>.011f||Math.abs((afterStamina-stamina)-2.5f)>.011f)throw new GameTestAssertException("committed blunt did not drive exact stamina/health");h.succeed();}catch(RuntimeException|Error e){NeoForge.EVENT_BUS.unregister(cancelListener);f.close();throw e;}});}catch(RuntimeException|Error e){NeoForge.EVENT_BUS.unregister(cancelListener);f.close();throw e;}}
    private static void runDead(GameTestHelper h){var f=player(h);var refs=new net.minecraft.world.entity.LivingEntity[2];h.testInfo.addListener(new net.minecraft.gametest.framework.GameTestListener(){private void clean(){for(var e:refs)if(e!=null&&!e.isRemoved())e.discard();f.close();}@Override public void testStructureLoaded(net.minecraft.gametest.framework.GameTestInfo i){}@Override public void testPassed(net.minecraft.gametest.framework.GameTestInfo i,net.minecraft.gametest.framework.GameTestRunner r){clean();}@Override public void testFailed(net.minecraft.gametest.framework.GameTestInfo i,net.minecraft.gametest.framework.GameTestRunner r){clean();}@Override public void testAddedForRerun(net.minecraft.gametest.framework.GameTestInfo o,net.minecraft.gametest.framework.GameTestInfo n,net.minecraft.gametest.framework.GameTestRunner r){clean();}});try{h.runAtTickTime(2,()->{try{var active=RegisteredPlayerReadyDriver.readyAndQuery(f);var a=active.body();refs[0]=a;var t=EntityType.VILLAGER.create(h.getLevel());if(t==null)throw new GameTestAssertException("target create failed");refs[1]=t;t.setNoAi(true);t.setPos(a.getX(),a.getY(),a.getZ()+.9);h.getLevel().addFreshEntity(t);t.setData(com.juicyslew.moonstation14.component.ModDataAttachments.DAMAGE.get(),new com.juicyslew.moonstation14.component.codec.attachment.DamageData(new com.juicyslew.moonstation14.component.codec.component.DamageMap(java.util.Map.of("blunt",100f))));t.setData(com.juicyslew.moonstation14.component.ModDataAttachments.MOB_STATE.get(),new com.juicyslew.moonstation14.ms14.mobs.MobStateAttachment(new com.juicyslew.moonstation14.ms14.mobs.MobStateData(com.juicyslew.moonstation14.ms14.character.components.MobStateComponent.State.DEAD,2)));t.setHealth(0);if(com.juicyslew.moonstation14.ms14.mobs.MobStateSystem.isDead(t)==false||t.isRemoved()||h.getLevel().getEntity(t.getUUID())!=t)throw new GameTestAssertException("retained-dead fixture not eligible");var sel=MeleeWeaponResolver.resolve(a).orElseThrow();CombatModeRequestService.handle(f.player(),new CombatModeRequest(active.epoch(),1,true));var before=typed(t);var r=MeleeAttackRequestService.handle(f.player(),new MeleeAttackRequest(active.epoch(),1,sel.kind(),sel.handRevision(),sel.activeHand(),sel.itemToken().orElse(""),t.getUUID()));if(r.status()!=MeleeAttackReply.Status.HIT||Math.abs((typed(t)-before)-5f)>.011f||t.getHealth()!=0||!com.juicyslew.moonstation14.ms14.mobs.MobStateSystem.isDead(t)||t.isRemoved()||h.getLevel().getEntity(t.getUUID())!=t)throw new GameTestAssertException("retained dead target did not preserve typed/native/dead state");h.succeed();}catch(RuntimeException|Error e){f.close();throw e;}});}catch(RuntimeException|Error e){f.close();throw e;}}
    private static float typed(net.minecraft.world.entity.LivingEntity e){var d=e.getExistingDataOrNull(com.juicyslew.moonstation14.component.ModDataAttachments.DAMAGE.get());return d==null?0f:d.getMap().getOrDefault("blunt",0f);}
